import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as r,af as s}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const k=JSON.parse('{"title":"Codex 术语表","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/codex/codex-glossary.md","filePath":"zh/products/ai-coding/codex/codex-glossary.md","lastUpdated":1787046041000}'),a={name:"zh/products/ai-coding/codex/codex-glossary.md"};function d(n,e,c,p,i,l){return r(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="codex-术语表" tabindex="-1">Codex 术语表 <a class="header-anchor" href="#codex-术语表" aria-label="Permalink to &quot;Codex 术语表&quot;">​</a></h1><blockquote><p>这是一份<strong>解释型</strong>文档——回答「这个概念是什么、为什么这样设计、什么时候该用」。和 <a href="./codex-cheatsheet.html">Codex 速查表</a> 互补：速查表回答「命令怎么写」，本文回答「为什么要这么写」。</p><p><strong>概念定义的唯一真相来源</strong>：本项目所有 Codex 文档中出现的概念，以本页的定义为准。其它页面只做「怎么用」的示范，不重复定义。</p><p><strong>文档站点变更提示</strong>：Codex 官方文档已从 <code>developers.openai.com/codex/*</code> 迁移至 <strong><code>learn.chatgpt.com/docs</code></strong>，旧地址会 308 永久重定向到新地址。本页所有官方链接均使用新地址。</p></blockquote><h2 id="概念关系图" tabindex="-1">概念关系图 <a class="header-anchor" href="#概念关系图" aria-label="Permalink to &quot;概念关系图&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                        ┌─────────────────────────┐</span></span>
<span class="line"><span>                        │   requirements.toml     │  管理员托管策略（最高约束）</span></span>
<span class="line"><span>                        │   企业/团队统一下发       │</span></span>
<span class="line"><span>                        └────────────┬────────────┘</span></span>
<span class="line"><span>                                     │ 收窄可选范围</span></span>
<span class="line"><span>                                     ▼</span></span>
<span class="line"><span>   ┌──────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>   │                    config.toml  配置层                        │</span></span>
<span class="line"><span>   │   ~/.codex/config.toml（用户级） &gt; .codex/config.toml（项目级） │</span></span>
<span class="line"><span>   │   Profile 配置档：$CODEX_HOME/&lt;name&gt;.config.toml               │</span></span>
<span class="line"><span>   └───────┬──────────────────────────┬───────────────────────────┘</span></span>
<span class="line"><span>           │                          │</span></span>
<span class="line"><span>           ▼                          ▼</span></span>
<span class="line"><span>   ┌───────────────┐          ┌──────────────────┐</span></span>
<span class="line"><span>   │  权限与沙箱     │          │  上下文与指令       │</span></span>
<span class="line"><span>   │  ─────────    │          │  ──────────      │</span></span>
<span class="line"><span>   │  approval_    │          │  AGENTS.md       │  ← 项目说明书</span></span>
<span class="line"><span>   │  policy       │          │  Rules           │  ← 结构化约束</span></span>
<span class="line"><span>   │  sandbox_mode │          │  Memories        │  ← 跨会话记忆</span></span>
<span class="line"><span>   │  trust_level  │          │  Compaction      │  ← 上下文压缩</span></span>
<span class="line"><span>   └───────┬───────┘          └────────┬─────────┘</span></span>
<span class="line"><span>           │                           │</span></span>
<span class="line"><span>           └───────────┬───────────────┘</span></span>
<span class="line"><span>                       ▼</span></span>
<span class="line"><span>           ┌───────────────────────┐</span></span>
<span class="line"><span>           │   Codex Agent 运行时   │</span></span>
<span class="line"><span>           │   会话 / Session       │</span></span>
<span class="line"><span>           └───────────┬───────────┘</span></span>
<span class="line"><span>                       │ 通过以下机制扩展能力</span></span>
<span class="line"><span>       ┌───────────────┼───────────────┬──────────────┐</span></span>
<span class="line"><span>       ▼               ▼               ▼              ▼</span></span>
<span class="line"><span>   ┌────────┐     ┌─────────┐    ┌─────────┐   ┌───────────┐</span></span>
<span class="line"><span>   │  MCP   │     │ Skills  │    │  Hooks  │   │ Subagents │</span></span>
<span class="line"><span>   │ 外部工具│     │ 可复用   │    │ 生命周期 │   │  子代理    │</span></span>
<span class="line"><span>   │        │     │ 流程     │    │ 拦截    │   │           │</span></span>
<span class="line"><span>   └───┬────┘     └────┬────┘    └─────────┘   └───────────┘</span></span>
<span class="line"><span>       │               │</span></span>
<span class="line"><span>       └───────┬───────┘</span></span>
<span class="line"><span>               ▼</span></span>
<span class="line"><span>        ┌─────────────┐</span></span>
<span class="line"><span>        │   Plugins   │  把 MCP / Skills / Hooks 打包分发</span></span>
<span class="line"><span>        └─────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   运行形态（同一套配置，四种入口）：</span></span>
<span class="line"><span>   CLI (codex) │ IDE 扩展 │ 桌面 App │ Web / Cloud</span></span></code></pre></div><p><strong>核心逻辑</strong>：最外层是<strong>约束</strong>（管理员托管 → 配置文件 → 权限沙箱），中间是<strong>上下文</strong>（AGENTS.md / Rules / Memories 决定 Codex 知道什么），最内层是<strong>能力扩展</strong>（MCP / Skills / Hooks / Subagents 决定 Codex 能做什么）。Plugins 不是新能力，只是前三者的打包分发格式。</p><p>理解这张图的实用价值：当 Codex 行为不符合预期时，按「约束 → 上下文 → 能力」的顺序自上而下排查，比随机改配置高效得多。</p><hr><h2 id="agents-md" tabindex="-1">AGENTS.md <a class="header-anchor" href="#agents-md" aria-label="Permalink to &quot;AGENTS.md {#agents-md}&quot;">​</a></h2><p><strong>是什么</strong></p><p>放在仓库里的 Markdown 文件，用自然语言告诉 Codex 这个项目的约定：用什么包管理器、改完代码要跑什么命令、哪些目录不要碰。可以类比新人入职时那份「团队约定文档」——只不过读者是 Agent。</p><p><strong>为什么需要</strong></p><p>不写 AGENTS.md，你就得在每次对话里重复交代「这个项目用 pnpm 不用 npm」。写了之后，这些约定变成每次任务自动加载的前置上下文。</p><p><strong>工作机制（指令链）</strong></p><p>Codex 启动时构建一条<strong>指令链</strong>（每次运行构建一次；在 TUI 中通常是每启动一个会话构建一次），发现顺序为：</p><ol><li><strong>全局作用域</strong>：在 Codex home 目录（默认 <code>~/.codex</code>，可用 <code>CODEX_HOME</code> 改）读取 <code>AGENTS.override.md</code>，不存在则读 <code>AGENTS.md</code>。这一层<strong>只取第一个非空文件</strong>。</li><li><strong>项目作用域</strong>：从项目根（通常是 Git 根）<strong>向下走到当前工作目录</strong>。每经过一个目录，依次检查 <code>AGENTS.override.md</code> → <code>AGENTS.md</code> → <code>project_doc_fallback_filenames</code> 里列出的备用文件名。<strong>每个目录最多取一个文件</strong>。</li><li><strong>合并顺序</strong>：从根往下拼接，用空行连接。<strong>离当前目录越近的文件出现在越后面，因此会覆盖前面的指导</strong>。</li></ol><p>Codex 会跳过空文件，并在合并后体积达到 <code>project_doc_max_bytes</code>（默认 32 KiB）时停止追加。</p><p><strong>关键细节</strong></p><table tabindex="0"><thead><tr><th>细节</th><th>说明</th></tr></thead><tbody><tr><td>覆盖而非替换</td><td><code>AGENTS.override.md</code> 存在时，同目录的 <code>AGENTS.md</code> 被忽略</td></tr><tr><td>只向下不向上</td><td>从项目根走到 cwd，走过头的目录不看</td></tr><tr><td>自定义文件名</td><td><code>project_doc_fallback_filenames = [&quot;TEAM_GUIDE.md&quot;, &quot;.agents.md&quot;]</code></td></tr><tr><td>提高上限</td><td><code>project_doc_max_bytes = 65536</code></td></tr><tr><td>代码评审规则</td><td>在最靠近被约束代码的 <code>AGENTS.md</code> 里加 <code>## Code Review Rules</code> 小节</td></tr><tr><td>临时全局覆盖</td><td>用 <code>~/.codex/AGENTS.override.md</code>，用完删掉即可恢复</td></tr></tbody></table><p><strong>与 Rules 的区别</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>AGENTS.md</th><th>Rules</th></tr></thead><tbody><tr><td>形态</td><td>自然语言 Markdown</td><td>结构化规则配置</td></tr><tr><td>用途</td><td>传达项目约定和背景</td><td>声明式约束与检查</td></tr><tr><td>覆盖粒度</td><td>按目录层级继承覆盖</td><td>按规则条目匹配</td></tr></tbody></table><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/docs/agent-configuration/agents-md" target="_blank" rel="noreferrer">Custom instructions with AGENTS.md</a></p><hr><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules {#rules}&quot;">​</a></h2><p><strong>是什么</strong></p><p>比 AGENTS.md 更结构化的约束机制，用来声明「什么情况下必须/禁止做什么」。项目级 Rules 属于 <code>.codex/</code> 项目层，因此同样受项目信任（trust level）的门控。</p><p><strong>为什么需要</strong></p><p>AGENTS.md 是自然语言，模型可能「理解偏了」。Rules 提供更明确的约束表达，也便于团队统一下发和审计。你可以用 <code>/debug-config</code> 查看当前生效的 rules。</p><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/docs/agent-configuration/rules" target="_blank" rel="noreferrer">Rules</a></p><hr><h2 id="sandbox" tabindex="-1">沙箱（Sandbox） <a class="header-anchor" href="#sandbox" aria-label="Permalink to &quot;沙箱（Sandbox） {#sandbox}&quot;">​</a></h2><p><strong>是什么</strong></p><p>限制 Codex 能读写哪些文件、能否访问网络的隔离层。它是<strong>机制层</strong>——决定「技术上能不能做」，与审批策略（决定「做之前要不要问你」）是两个独立的维度。</p><p><strong>三种模式</strong></p><table tabindex="0"><thead><tr><th><code>sandbox_mode</code></th><th>含义</th><th>典型场景</th></tr></thead><tbody><tr><td><code>read-only</code></td><td>只读，不能改文件</td><td>代码审查、架构分析</td></tr><tr><td><code>workspace-write</code></td><td>可写工作区</td><td>日常开发（常用默认）</td></tr><tr><td><code>danger-full-access</code></td><td>无沙箱限制</td><td>明确知道风险时才用</td></tr></tbody></table><p><code>workspace-write</code> 下可进一步微调：</p><table tabindex="0"><thead><tr><th>配置键</th><th>作用</th></tr></thead><tbody><tr><td><code>sandbox_workspace_write.writable_roots</code></td><td>追加可写根目录</td></tr><tr><td><code>sandbox_workspace_write.network_access</code></td><td>是否允许网络访问</td></tr><tr><td><code>sandbox_workspace_write.exclude_slash_tmp</code></td><td>把 <code>/tmp</code> 排除出可写范围</td></tr><tr><td><code>sandbox_workspace_write.exclude_tmpdir_env_var</code></td><td>把 <code>$TMPDIR</code> 排除出可写范围</td></tr></tbody></table><p><strong>为什么沙箱和审批要分开</strong></p><p>因为「安全」有两条独立的防线：沙箱是<strong>硬边界</strong>（越不过去），审批是<strong>人工闸门</strong>（越过去之前先问你）。只有审批没有沙箱，一次误点「同意」就可能造成破坏；只有沙箱没有审批，Codex 会在边界内自由行动而你毫不知情。两者组合才能既高效又可控。</p><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/docs/sandboxing" target="_blank" rel="noreferrer">Sandboxing</a></p><hr><h2 id="approval-policy-and-permissions" tabindex="-1">审批策略（Approval policy）与权限 <a class="header-anchor" href="#approval-policy-and-permissions" aria-label="Permalink to &quot;审批策略（Approval policy）与权限 {#approval-policy-and-permissions}&quot;">​</a></h2><p><strong>是什么</strong></p><p>决定 Codex 执行动作前是否需要你确认的策略。注意配置层和界面层用了<strong>两套命名</strong>，这是初学者最容易混淆的地方。</p><p><strong>配置层：<code>approval_policy</code></strong></p><table tabindex="0"><thead><tr><th>取值</th><th>含义</th></tr></thead><tbody><tr><td><code>untrusted</code></td><td>只自动执行被认为安全的操作，其余都要问</td></tr><tr><td><code>on-request</code></td><td>由模型按需请求审批</td></tr><tr><td><code>never</code></td><td>从不询问</td></tr><tr><td><code>{ granular = { ... } }</code></td><td>细粒度控制，可分别设置 <code>sandbox_approval</code>、<code>rules</code>、<code>mcp_elicitations</code>、<code>request_permissions</code>、<code>skill_approval</code></td></tr></tbody></table><blockquote><p>旧取值 <code>on-failure</code> 已废弃。命令行上可用 <code>--ask-for-approval &lt;policy&gt;</code> 临时指定。</p></blockquote><p><strong>界面层：TUI 权限模式</strong></p><p>在 TUI 里用 <code>/permissions</code> 切换，显示为三个档位：<strong>Auto</strong>（默认）、<strong>Read-only</strong>、<strong>Full Access</strong>。</p><p><strong>为什么有两套名字</strong></p><p>配置层描述的是「审批请求如何产生」，界面层描述的是「组合出的实用档位」——Read-only 和 Full Access 实际上同时调整了沙箱和审批两个维度。写文档或排查问题时必须说清自己在讲哪一层，否则沟通必然错位。</p><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/docs/permissions" target="_blank" rel="noreferrer">Permissions</a></p><hr><h2 id="project-trust-and-config-layering" tabindex="-1">项目信任（Trust level）与配置层级 <a class="header-anchor" href="#project-trust-and-config-layering" aria-label="Permalink to &quot;项目信任（Trust level）与配置层级 {#project-trust-and-config-layering}&quot;">​</a></h2><p><strong>是什么</strong></p><p>Codex 是否信任某个项目目录的开关，配置在 <code>projects.&lt;path&gt;.trust_level</code>，取值 <code>&quot;trusted&quot;</code> 或 <code>&quot;untrusted&quot;</code>。</p><p><strong>为什么需要</strong></p><p>因为项目里的 <code>.codex/</code> 目录是<strong>别人可以往仓库里提交的内容</strong>。如果 clone 一个陌生仓库就自动加载它的配置、hooks 和 rules，等于把执行权交给了仓库作者。信任门控就是这道防线：<strong>未信任的项目会跳过所有项目级 <code>.codex/</code> 层</strong>（配置、hooks、rules 都不加载）。</p><p><strong>配置优先级</strong></p><p>官方 <a href="https://learn.chatgpt.com/docs/config-file/config-basic" target="_blank" rel="noreferrer">Config basics</a> 的解析顺序（高优先在前）：</p><ol><li>CLI flag 与 <code>-c</code> / <code>--config</code> 覆盖</li><li>项目 <code>.codex/config.toml</code>（从仓库根走到当前目录，近的覆盖远的）——<strong>仅信任项目会加载</strong></li><li><code>--profile</code> 选中的 profile 文件（<code>$CODEX_HOME/&lt;name&gt;.config.toml</code>）</li><li>用户配置：<code>~/.codex/config.toml</code></li><li>系统配置（若存在）：Unix 上的 <code>/etc/codex/config.toml</code></li><li>内置默认值</li></ol><p>被信任的项目配置<strong>会</strong>覆盖用户配置里的同名键。这是官方顺序。项目配置做不到的是另一条规则：下面这组机器本地键在项目层会被 <strong>忽略</strong>：</p><p><code>openai_base_url</code>、<code>chatgpt_base_url</code>、<code>apps_mcp_product_sku</code>、<code>model_provider</code>、<code>model_providers</code>、<code>notify</code>、<code>profile</code>、<code>profiles</code>、<code>experimental_realtime_ws_base_url</code>、<code>otel</code></p><p>这个设计的用意很直接：<strong>仓库不能悄悄把你的模型请求改道到别的服务端</strong>。</p><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/docs/config-file/config-reference" target="_blank" rel="noreferrer">Config Reference</a></p><hr><h2 id="profiles" tabindex="-1">Profile（配置档） <a class="header-anchor" href="#profiles" aria-label="Permalink to &quot;Profile（配置档） {#profiles}&quot;">​</a></h2><p><strong>是什么</strong></p><p>一组命名的配置集合，用于在不同场景间切换（例如工作项目 vs 个人实验）。</p><p><strong>工作机制</strong></p><p>Profile 文件与 <code>config.toml</code> 同级存放，命名为 <code>$CODEX_HOME/&lt;profile-name&gt;.config.toml</code>，用 <code>--profile &lt;profile-name&gt;</code> 选中。</p><p><strong>与 <code>CODEX_HOME</code> 的区别</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>Profile</th><th><code>CODEX_HOME</code></th></tr></thead><tbody><tr><td>切换的是</td><td>同一个 home 里的一份配置</td><td>整个 Codex home 目录</td></tr><tr><td>隔离程度</td><td>只隔离配置</td><td>配置、会话、日志全部隔离</td></tr><tr><td>典型用途</td><td>工作/个人两套模型与权限</td><td>CI 里用独立的自动化身份</td></tr></tbody></table><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/docs/config-file/config-reference" target="_blank" rel="noreferrer">Config Reference</a>、<a href="https://learn.chatgpt.com/docs/config-file/environment-variables" target="_blank" rel="noreferrer">Environment Variables</a></p><hr><h2 id="mcp-model-context-protocol" tabindex="-1">MCP（Model Context Protocol） <a class="header-anchor" href="#mcp-model-context-protocol" aria-label="Permalink to &quot;MCP（Model Context Protocol） {#mcp-model-context-protocol}&quot;">​</a></h2><p><strong>是什么</strong></p><p>让 Codex 连接外部工具和数据源的开放协议。可以理解成 AI 世界的「USB 接口」——协议统一之后，任何实现了 MCP 的服务都能被 Codex 直接使用，不需要 Codex 为每个服务单独适配。</p><p><strong>为什么重要</strong></p><p>没有 MCP，Agent 只能读写本地文件和跑命令。有了 MCP，同一个 Agent 可以查数据库、调内部 API、访问设计稿——而且这些能力的提供方和 Codex 是解耦的。</p><p><strong>配置形态（重要纠错点）</strong></p><p><code>mcp_servers</code> 是<strong>以 id 为键的表（table）</strong>，不是数组表：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcp_servers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">filesystem</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">command = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;npx&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">args = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-y&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@modelcontextprotocol/server-filesystem&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;.&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>常用键：</p><table tabindex="0"><thead><tr><th>键</th><th>说明</th></tr></thead><tbody><tr><td><code>command</code> / <code>args</code> / <code>cwd</code> / <code>env</code></td><td>STDIO 方式启动本地进程</td></tr><tr><td><code>url</code> / <code>http_headers</code> / <code>bearer_token_env_var</code></td><td>流式 HTTP 方式连接远端</td></tr><tr><td><code>enabled</code> / <code>required</code></td><td>是否启用、是否必需</td></tr><tr><td><code>enabled_tools</code> / <code>disabled_tools</code></td><td>工具级白/黑名单</td></tr><tr><td><code>default_tools_approval_mode</code></td><td><code>auto</code> / <code>prompt</code> / <code>approve</code></td></tr><tr><td><code>startup_timeout_sec</code></td><td>启动超时，默认 10</td></tr><tr><td><code>tool_timeout_sec</code></td><td>单次调用超时，默认 60</td></tr></tbody></table><p><strong>双向角色</strong></p><p>Codex 既可以作为 MCP <strong>客户端</strong>消费别人的服务，也可以作为 MCP <strong>服务端</strong>被别的 Agent 调用（见 <code>codex mcp</code> 与 MCP Server 文档）。</p><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/docs/extend/mcp?surface=cli" target="_blank" rel="noreferrer">MCP</a>、<a href="https://learn.chatgpt.com/docs/mcp-server" target="_blank" rel="noreferrer">MCP Server</a></p><hr><h2 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;Skills {#skills}&quot;">​</a></h2><p><strong>是什么</strong></p><p>把一段可复用的工作流程封装成「技能」，让 Codex 在合适的时机自动调用。你可以用 <code>/skills</code> 查看当前可用技能。</p><p><strong>与 MCP 的区别</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>Skills</th><th>MCP</th></tr></thead><tbody><tr><td>本质</td><td>打包的<strong>流程/知识</strong></td><td>接入的<strong>工具/数据</strong></td></tr><tr><td>谁执行</td><td>Codex 自己按流程做</td><td>外部服务执行后返回结果</td></tr><tr><td>典型内容</td><td>「发布流程分七步」</td><td>「查询生产数据库」</td></tr></tbody></table><p>简单判断：需要<strong>接一个外部系统</strong>用 MCP；需要<strong>固化一套做法</strong>用 Skills。</p><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/docs/build-skills" target="_blank" rel="noreferrer">Skills</a></p><hr><h2 id="hooks" tabindex="-1">Hooks <a class="header-anchor" href="#hooks" aria-label="Permalink to &quot;Hooks {#hooks}&quot;">​</a></h2><p><strong>是什么</strong></p><p>在 Codex 生命周期的特定节点自动触发的命令，用于做强制检查或自动化动作。可以内联写在 <code>config.toml</code> 里。</p><p><strong>支持的事件</strong></p><p><code>PreToolUse</code>、<code>PermissionRequest</code>、<code>PostToolUse</code>、<code>PreCompact</code>、<code>PostCompact</code>、<code>SessionStart</code>、<code>SubagentStart</code>、<code>SubagentStop</code>、<code>UserPromptSubmit</code>、<code>Stop</code></p><p><strong>当前限制</strong>：只支持 command 类型的 hook（prompt / agent 类型会被解析但跳过执行）。Windows 上可用 <code>commandWindows</code>（TOML 中写作 <code>command_windows</code>）指定平台差异命令。</p><p><strong>与 AGENTS.md 的区别</strong></p><p>AGENTS.md 是<strong>建议</strong>——模型可能不照做；Hooks 是<strong>强制</strong>——脚本一定会跑。要求「每次改完代码必须格式化」这类硬约束，写 Hooks 而不是写 AGENTS.md。</p><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/docs/hooks" target="_blank" rel="noreferrer">Hooks</a></p><hr><h2 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins {#plugins}&quot;">​</a></h2><p><strong>是什么</strong></p><p>把 MCP 服务、Skills、Hooks 打包成一个可分发单元的格式。用 <code>/plugins</code> 管理。</p><p><strong>为什么需要</strong></p><p>团队里每个人手动配一遍 MCP + Skills + Hooks 不现实，也容易配错。Plugins 让「一套 Codex 工作环境」变成可以一次安装的东西。</p><p><strong>生态角色</strong>：Plugins 是<strong>分发层</strong>，不引入新能力。配置上它可以覆盖所打包的 MCP 服务的启用状态与工具审批模式（<code>plugins.&lt;plugin&gt;.mcp_servers.&lt;server&gt;.*</code>）。</p><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/docs/plugins" target="_blank" rel="noreferrer">Plugins</a></p><hr><h2 id="subagents" tabindex="-1">Subagents（子代理） <a class="header-anchor" href="#subagents" aria-label="Permalink to &quot;Subagents（子代理） {#subagents}&quot;">​</a></h2><p><strong>是什么</strong></p><p>主 Agent 派生出的独立 Agent，用于并行处理或隔离上下文。用 <code>/agent</code> 管理，在 <code>[agents]</code> 配置段声明。</p><p><strong>关键行为</strong>：<strong>只有你明确要求时才会派生子代理</strong>——不会自动发生。</p><p><strong>相关配置</strong></p><table tabindex="0"><thead><tr><th>键</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>agents.max_depth</code></td><td>1</td><td>嵌套深度上限</td></tr><tr><td><code>agents.max_threads</code></td><td>6</td><td>并发线程上限</td></tr><tr><td><code>agents.job_max_runtime_seconds</code></td><td>1800</td><td>单任务运行时长上限</td></tr><tr><td><code>agents.&lt;name&gt;.config_file</code></td><td>—</td><td>子代理使用的配置文件</td></tr><tr><td><code>agents.&lt;name&gt;.description</code></td><td>—</td><td>描述，影响何时被选用</td></tr></tbody></table><p>启用 <code>features.multi_agent</code> 后可用的工具：<code>spawn_agent</code>、<code>send_input</code>、<code>resume_agent</code>、<code>wait_agent</code>、<code>close_agent</code>。</p><p><strong>什么时候该用</strong></p><p>需要<strong>上下文隔离</strong>时（比如让一个子代理专门做对抗性审查，避免它被主线的思路带偏），或需要<strong>并行</strong>处理互不依赖的任务时。任务之间有强依赖的，串行做反而更快。</p><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/docs/agent-configuration/subagents" target="_blank" rel="noreferrer">Subagents</a></p><hr><h2 id="memories" tabindex="-1">Memories（记忆） <a class="header-anchor" href="#memories" aria-label="Permalink to &quot;Memories（记忆） {#memories}&quot;">​</a></h2><p><strong>是什么</strong></p><p>跨会话保留的信息，让 Codex 记住你的偏好和项目背景，不必每次重新交代。用 <code>/memories</code> 管理。</p><p><strong>与 AGENTS.md 的区别</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>Memories</th><th>AGENTS.md</th></tr></thead><tbody><tr><td>来源</td><td>Codex 自动提炼 + 你确认</td><td>你手写</td></tr><tr><td>存放</td><td>Codex 侧</td><td>仓库里，可提交、可评审</td></tr><tr><td>适合</td><td>个人习惯、渐进积累的经验</td><td>团队约定，需要所有人一致</td></tr></tbody></table><p>判断标准很简单：<strong>这条信息该让团队所有人共享吗</strong>？该，就写进 AGENTS.md 提交上去；只是你个人习惯，交给 Memories。</p><p><strong>相关配置</strong>：<code>features.memories</code>（默认关闭）；细项在 <code>memories.*</code>，如 <code>use_memories</code>、<code>generate_memories</code>、<code>max_unused_days</code>、<code>max_rollout_age_days</code> 等。</p><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/docs/customization/memories?surface=app" target="_blank" rel="noreferrer">Memories</a></p><hr><h2 id="sessions-and-compaction" tabindex="-1">会话（Session）与上下文压缩（Compaction） <a class="header-anchor" href="#sessions-and-compaction" aria-label="Permalink to &quot;会话（Session）与上下文压缩（Compaction） {#sessions-and-compaction}&quot;">​</a></h2><p><strong>是什么</strong></p><p>一次连续对话及其累积的上下文。会话记录存放在 <code>~/.codex/sessions/</code>。</p><p><strong>会话操作</strong></p><table tabindex="0"><thead><tr><th>操作</th><th>命令</th></tr></thead><tbody><tr><td>恢复会话（选择器）</td><td><code>codex resume</code></td></tr><tr><td>恢复最近一次</td><td><code>codex resume --last</code></td></tr><tr><td>恢复指定会话</td><td><code>codex resume &lt;SESSION_ID&gt;</code></td></tr><tr><td>列出全部</td><td><code>codex resume --all</code></td></tr><tr><td>从当前状态分叉</td><td><code>/fork</code></td></tr><tr><td>归档 / 取消归档</td><td><code>/archive</code>、<code>codex unarchive &lt;SESSION&gt;</code></td></tr></tbody></table><p>会话 ID 可以从会话选择器、<code>/status</code> 或 <code>~/.codex/sessions/</code> 目录取得。</p><p><strong>上下文压缩（Compaction）</strong></p><p>上下文接近上限时，把早期对话压缩成摘要以腾出空间。手动触发用 <code>/compact</code>；自动触发阈值由 <code>model_auto_compact_token_limit</code> 控制。<code>PreCompact</code> / <code>PostCompact</code> 两个 hook 事件可以在压缩前后插入动作。</p><p><strong>为什么要主动管理</strong></p><p>压缩是有损的——摘要会丢细节。与其等它自动压缩，不如在任务切换时主动 <code>/clear</code> 或开新会话。一个会话只做一件事，比一个会话做十件事然后被迫压缩要可靠得多。</p><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/docs/developer-commands?surface=cli" target="_blank" rel="noreferrer">Slash commands</a></p><hr><h2 id="web-search-modes" tabindex="-1">Web 搜索模式 <a class="header-anchor" href="#web-search-modes" aria-label="Permalink to &quot;Web 搜索模式 {#web-search-modes}&quot;">​</a></h2><p><strong>是什么</strong></p><p>Codex 获取外部网页信息的能力，有四档（重要纠错点：这是<strong>枚举字符串</strong>，不是布尔开关）。</p><table tabindex="0"><thead><tr><th><code>web_search</code></th><th>含义</th></tr></thead><tbody><tr><td><code>disabled</code></td><td>关闭</td></tr><tr><td><code>cached</code></td><td><strong>默认值</strong>，查询 OpenAI 维护的索引，不实时抓取</td></tr><tr><td><code>indexed</code></td><td>仅当搜索索引放行时才允许外部网页访问</td></tr><tr><td><code>live</code></td><td>实时抓取；在 <code>--yolo</code> / 全权限模式下默认变为此值</td></tr></tbody></table><p>命令行上用<strong>裸 <code>--search</code></strong>（不带参数）开启实时搜索。搜索结果会以 <code>web_search</code> 条目出现在对话记录和 <code>codex exec --json</code> 输出里。</p><blockquote><p>旧的开关式配置 <code>features.web_search</code>、<code>features.web_search_cached</code>、<code>features.web_search_request</code> 已废弃。</p></blockquote><p><strong>为什么默认是 cached 而不是 live</strong></p><p>缓存索引更快、更省，而且对绝大多数「这个 API 怎么用」的问题足够。只有在查非常新的信息（比如刚发布的版本）时才需要 <code>live</code>。</p><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/docs/config-file/config-reference" target="_blank" rel="noreferrer">Config Reference</a></p><hr><h2 id="non-interactive-mode-codex-exec" tabindex="-1">非交互模式（<code>codex exec</code>） <a class="header-anchor" href="#non-interactive-mode-codex-exec" aria-label="Permalink to &quot;非交互模式（\`codex exec\`） {#non-interactive-mode-codex-exec}&quot;">​</a></h2><p><strong>是什么</strong></p><p>不进 TUI、直接跑完一个任务就退出的运行方式，用于脚本和 CI。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;run the test suite and fix any failures&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;summarize recent changes&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> resume</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --last</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;now add tests for the new function&quot;</span></span></code></pre></div><p><strong>为什么需要独立的子命令</strong></p><p>因为 CI 里没有终端交互，也不该有人工审批等待。<code>codex exec</code> 明确表达「这是一次性的、无人值守的运行」，日志默认级别是 <code>RUST_LOG=error</code>，输出便于机器解析。</p><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/docs/non-interactive-mode" target="_blank" rel="noreferrer">Non-interactive Mode</a></p><hr><h2 id="运行形态-cli-ide-app-cloud" tabindex="-1">运行形态：CLI / IDE / App / Cloud <a class="header-anchor" href="#运行形态-cli-ide-app-cloud" aria-label="Permalink to &quot;运行形态：CLI / IDE / App / Cloud&quot;">​</a></h2><p><strong>是什么</strong></p><p>同一个 Codex Agent 的四种入口。它们共享同一套配置模型（<code>config.toml</code>、AGENTS.md、MCP、Skills），差异在交互方式和运行位置。</p><table tabindex="0"><thead><tr><th>形态</th><th>入口</th><th>特点</th></tr></thead><tbody><tr><td>CLI</td><td><code>codex</code></td><td>终端 TUI，脚本化能力最强</td></tr><tr><td>IDE 扩展</td><td>编辑器内</td><td>与编辑器上下文结合</td></tr><tr><td>桌面 App</td><td>独立应用</td><td>图形界面、多线程会话管理</td></tr><tr><td>Web / Cloud</td><td><code>codex cloud</code></td><td>在云端环境里跑，任务可并行多次尝试</td></tr></tbody></table><p><strong>云端相关命令</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cloud</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                              # 打开云端界面（Ctrl+O 可查看环境 ID）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cloud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ENV_I</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;...&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 在指定云环境执行</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cloud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ENV_I</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --attempts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;...&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 同一任务尝试多次（1-4）</span></span></code></pre></div><p><strong>远程控制</strong>：<code>codex app-server --listen ws://127.0.0.1:4500</code> 起服务，<code>codex --remote ws://127.0.0.1:4500</code> 连接。<code>--remote</code> 支持 <code>ws://</code>、<code>wss://</code>、<code>unix://</code>。跨网络使用时必须走 <code>wss://</code> 并配置鉴权。</p><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/docs/codex/cli" target="_blank" rel="noreferrer">CLI</a>、<a href="https://learn.chatgpt.com/docs/codex/ide" target="_blank" rel="noreferrer">IDE Extension</a>、<a href="https://learn.chatgpt.com/docs/app-server" target="_blank" rel="noreferrer">App Server</a></p><hr><h2 id="requirementstoml-managed-policy" tabindex="-1">requirements.toml（托管策略） <a class="header-anchor" href="#requirementstoml-managed-policy" aria-label="Permalink to &quot;requirements.toml（托管策略） {#requirementstoml-managed-policy}&quot;">​</a></h2><p><strong>是什么</strong></p><p>管理员下发的策略文件，用于在组织范围内<strong>收窄</strong>可选项——它不是「又一份配置」，而是配置的上界。</p><p><strong>能约束什么</strong></p><table tabindex="0"><thead><tr><th>键</th><th>作用</th></tr></thead><tbody><tr><td><code>allowed_approval_policies</code></td><td>允许的审批策略集合（如 <code>untrusted</code>、<code>on-request</code>、<code>never</code>、<code>granular</code>）</td></tr><tr><td><code>allowed_sandbox_modes</code></td><td>允许的沙箱模式集合</td></tr><tr><td><code>allowed_web_search_modes</code></td><td>允许的搜索模式；<code>disabled</code> 总是允许，空列表等于只允许 <code>disabled</code></td></tr><tr><td><code>allowed_permission_profiles</code></td><td>允许的权限档位；<strong>需要 Codex 0.138.0+</strong></td></tr><tr><td><code>default_permissions</code></td><td>默认权限档，必须在允许列表内</td></tr><tr><td><code>allow_managed_hooks_only</code></td><td>只执行托管 hooks，跳过用户/项目/会话/插件 hooks</td></tr><tr><td><code>features.*</code></td><td>用与 <code>config.toml</code> 相同的键名锁定特性开关</td></tr><tr><td><code>mcp_servers</code> 白名单</td><td>需同时指定 id 与 <code>identity</code>（<code>identity.command</code> 或 <code>identity.url</code>）</td></tr><tr><td><code>marketplaces.*</code></td><td>限制插件来源（<code>git</code> / <code>host_pattern</code> / <code>local</code>）</td></tr><tr><td><code>enforce_residency</code></td><td>数据驻留，当前仅支持 <code>us</code></td></tr></tbody></table><blockquote><p><strong>版本注意</strong>：0.137.0 及更早版本会忽略 <code>allowed_permission_profiles</code> 与托管的 <code>default_permissions</code>。要靠这两项做强制约束，必须先确保客户端版本 ≥ 0.138.0。</p></blockquote><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/docs/config-file/config-reference" target="_blank" rel="noreferrer">Config Reference</a></p><hr><h2 id="模型与推理强度" tabindex="-1">模型与推理强度 <a class="header-anchor" href="#模型与推理强度" aria-label="Permalink to &quot;模型与推理强度&quot;">​</a></h2><p><strong>是什么</strong></p><p>Codex 使用的模型，以及模型「想多久」的档位。</p><table tabindex="0"><thead><tr><th>配置键</th><th>取值</th><th>说明</th></tr></thead><tbody><tr><td><code>model</code></td><td>字符串</td><td>官方 Config basics 示例为 <code>gpt-5.6</code>；名称会变，以 <a href="https://learn.chatgpt.com/docs/models" target="_blank" rel="noreferrer">Models</a> 为准</td></tr><tr><td><code>model_reasoning_effort</code></td><td><code>minimal</code> / <code>low</code> / <code>medium</code> / <code>high</code> / <code>xhigh</code></td><td>仅 Responses API 支持</td></tr><tr><td><code>model_reasoning_summary</code></td><td><code>auto</code> / <code>concise</code> / <code>detailed</code> / <code>none</code></td><td>推理摘要详细程度</td></tr><tr><td><code>model_verbosity</code></td><td><code>low</code> / <code>medium</code> / <code>high</code></td><td>输出详细程度</td></tr></tbody></table><p>命令行上可用 <code>--model &lt;name&gt;</code> 临时切换，或 <code>/model</code> 在会话中切换。</p><p><strong>怎么选推理强度</strong></p><p>改一行配置、加个日志——<code>low</code> 够了。设计模块边界、排查复杂并发 bug——<code>high</code> 或 <code>xhigh</code> 值得多等。默认 <code>medium</code> 适用于大多数日常任务。盲目全开 <code>xhigh</code> 只会让简单任务变慢，还更快耗尽额度。</p><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/docs/models" target="_blank" rel="noreferrer">Models</a></p><hr><h2 id="chat-work-codex" tabindex="-1">Chat / Work / Codex <a class="header-anchor" href="#chat-work-codex" aria-label="Permalink to &quot;Chat / Work / Codex {#chat-work-codex}&quot;">​</a></h2><p><strong>是什么</strong></p><p>同一 ChatGPT 应用里的三种工作方式，不是三个独立安装包。官方对照在 <a href="https://learn.chatgpt.com/docs/use-chatgpt" target="_blank" rel="noreferrer">Use ChatGPT</a>。</p><table tabindex="0"><thead><tr><th>名字</th><th>是什么</th><th>不是什么</th></tr></thead><tbody><tr><td><strong>Chat</strong></td><td>问答、短草稿、把设计谈清楚</td><td>不是编程界面</td></tr><tr><td><strong>ChatGPT Work</strong></td><td>把任务做到可审成品（PPT / 表 / 站点 / 定期更新）</td><td>不是 Codex；没有 PR 侧栏</td></tr><tr><td><strong>Codex</strong></td><td>编程 Agent：仓库、diff、测试、PR</td><td>不是闲聊入口</td></tr></tbody></table><p>2026-07-09 起独立 Codex 桌面应用并入 ChatGPT 桌面应用。Work 与 Codex 共用用量额度。</p><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/docs/use-chatgpt" target="_blank" rel="noreferrer">Use ChatGPT</a> · <a href="./chatgpt-work.html">ChatGPT Work</a></p><hr><h2 id="chatgpt-work" tabindex="-1">ChatGPT Work <a class="header-anchor" href="#chatgpt-work" aria-label="Permalink to &quot;ChatGPT Work {#chatgpt-work}&quot;">​</a></h2><p><strong>是什么</strong></p><p>官方原文：<em>ChatGPT Work is a way to delegate real work to ChatGPT.</em> 网页默认跑在云端；桌面可选 <strong>Work locally</strong> 摸本机文件和应用。</p><p><strong>和 Codex 的区别</strong></p><p>能力可以重叠（官方允许继续用 Codex 做非编程工作），界面不同：Work 藏起 Git / shell，面向日常知识工作。前端工程师用它写周报、出 Sites、盯 Slack，改仓库仍走 Codex。</p><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/docs/get-started-with-work" target="_blank" rel="noreferrer">Get started with Work</a> · 本教程 <a href="./chatgpt-work.html">ChatGPT Work</a></p><hr><h2 id="sites" tabindex="-1">Sites <a class="header-anchor" href="#sites" aria-label="Permalink to &quot;Sites {#sites}&quot;">​</a></h2><p><strong>是什么</strong></p><p>ChatGPT 创建、托管、分享网站和应用的工作流，公开测试。入口 <a href="https://chatgpt.com/sites" target="_blank" rel="noreferrer">chatgpt.com/sites</a>。</p><p><strong>不是什么</strong></p><p>不是 Claude Design。没有「从代码库抽品牌规范再交接实现」的官方产品。每个部署 URL 都是生产环境。</p><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/docs/sites" target="_blank" rel="noreferrer">Sites</a> · 本教程 <a href="./sites.html">Sites</a></p><hr><h2 id="codex-cloud" tabindex="-1">Codex Cloud 与托管评审 <a class="header-anchor" href="#codex-cloud" aria-label="Permalink to &quot;Codex Cloud 与托管评审 {#codex-cloud}&quot;">​</a></h2><p><strong>是什么</strong></p><p>在 OpenAI 托管的隔离环境里跑编程任务，可并行，可从 GitHub / Linear / Slack 派活。入口 <a href="https://chatgpt.com/codex" target="_blank" rel="noreferrer">chatgpt.com/codex</a>。</p><p><strong>托管评审</strong></p><p>Cloud 上的 code review / QA 对合格客户由 <strong>GPT-5.6 Sol</strong> 驱动，模型由 Cloud 自动选。Codex Security Review 是另一条研究预览（Enterprise / Business / Edu / Pro，不含 Plus）。本机 <code>/review</code> 仍是本地会话里的评审，不要和托管评审混名。</p><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/docs/cloud" target="_blank" rel="noreferrer">Codex cloud</a> · <a href="https://learn.chatgpt.com/docs/whats-new" target="_blank" rel="noreferrer">What&#39;s new</a> · 本教程 <a href="./codex-cloud.html">Cloud</a></p><hr><h2 id="codex-ide-extension" tabindex="-1">Codex IDE 扩展 <a class="header-anchor" href="#codex-ide-extension" aria-label="Permalink to &quot;Codex IDE 扩展 {#codex-ide-extension}&quot;">​</a></h2><p><strong>是什么</strong></p><p>编辑器入口：打开的文件和选区进提示词；在源码旁边审 focused diff。配置模型和 CLI 相同。</p><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/codex/ide" target="_blank" rel="noreferrer">IDE</a> · 本教程 <a href="./codex-ide.html">IDE</a></p><hr><h2 id="codex-remote" tabindex="-1">Codex Remote <a class="header-anchor" href="#codex-remote" aria-label="Permalink to &quot;Codex Remote {#codex-remote}&quot;">​</a></h2><p><strong>是什么</strong></p><p>手机（或另一台桌面）带一台<strong>已配对</strong>的 Mac / Windows 主机。干活的是主机。不是 Cloud。</p><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/codex/remote" target="_blank" rel="noreferrer">Remote</a> · 本教程 <a href="./codex-remote.html">Remote</a></p><hr><h2 id="codex-security" tabindex="-1">Codex Security <a class="header-anchor" href="#codex-security" aria-label="Permalink to &quot;Codex Security {#codex-security}&quot;">​</a></h2><p><strong>是什么</strong></p><p>应用安全 Agent，三扇门：桌面插件、CLI/SDK（<code>@openai/codex-security</code>）、Cloud（研究预览）。只扫你有权评估的代码。</p><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/codex/security" target="_blank" rel="noreferrer">Security</a> · 本教程 <a href="./codex-security.html">Security</a></p><hr><h2 id="chrome-extension" tabindex="-1">Chrome 扩展 <a class="header-anchor" href="#chrome-extension" aria-label="Permalink to &quot;Chrome 扩展 {#chrome-extension}&quot;">​</a></h2><p><strong>是什么</strong></p><p>让 ChatGPT 控制<strong>你的</strong> Chrome 配置，含已登录标签。不同于 <code>@Browser</code>（内置配置）和 Work 未登录的云端浏览器。</p><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/codex/chrome-extension" target="_blank" rel="noreferrer">Chrome extension</a> · 本教程 <a href="./codex-chrome.html">Chrome</a></p><hr><h2 id="computer-use" tabindex="-1">Computer Use <a class="header-anchor" href="#computer-use" aria-label="Permalink to &quot;Computer Use {#computer-use}&quot;">​</a></h2><p><strong>是什么</strong></p><p>桌面应用能力：ChatGPT 看见并操作 macOS / Windows 上的 GUI。Windows 会占前台。文件 / shell 仍走沙箱和审批。</p><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/docs/computer-use" target="_blank" rel="noreferrer">Computer Use</a></p><hr><h2 id="browser" tabindex="-1">Browser <a class="header-anchor" href="#browser" aria-label="Permalink to &quot;Browser {#browser}&quot;">​</a></h2><p><strong>是什么</strong></p><p>要么是桌面<strong>内置</strong>浏览器（<code>@Browser</code>，单独配置），要么是 Work 的<strong>云端</strong>浏览器（未登录的公开站点）。CLI 和 IDE 扩展里没有。</p><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/docs/browser" target="_blank" rel="noreferrer">Browser</a></p><hr><h2 id="chatgpt-voice" tabindex="-1">ChatGPT Voice <a class="header-anchor" href="#chatgpt-voice" aria-label="Permalink to &quot;ChatGPT Voice {#chatgpt-voice}&quot;">​</a></h2><p><strong>是什么</strong></p><p>桌面应用里 Chat / Work / Codex 的 GPT-Live 语音（配对后也可走 iOS Remote）。会话必须<strong>以语音模式开始</strong>。Voice 额度单独滚动；任务仍消耗 Codex 配额。</p><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/docs/features/voice" target="_blank" rel="noreferrer">Voice</a></p><hr><h2 id="computer-history" tabindex="-1">Computer History <a class="header-anchor" href="#computer-history" aria-label="Permalink to &quot;Computer History {#computer-history}&quot;">​</a></h2><p><strong>是什么</strong></p><p>macOS 桌面功能（默认关），把允许的应用 / 网站活动变成记忆和时间线。依赖 Memories。EEA / 瑞士 / 英国不可用。替代 Chronicle 预览。</p><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/docs/customization/computer-history" target="_blank" rel="noreferrer">Computer History</a></p><hr><h2 id="codex-sdk" tabindex="-1">Codex SDK <a class="header-anchor" href="#codex-sdk" aria-label="Permalink to &quot;Codex SDK {#codex-sdk}&quot;">​</a></h2><p><strong>是什么</strong></p><p>启动和恢复<strong>本机</strong> Codex 线程的库：TypeScript <code>@openai/codex-sdk</code>，Python <code>openai-codex</code>。结构化安全 findings 改用 <code>@openai/codex-security</code>。</p><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/docs/codex-sdk" target="_blank" rel="noreferrer">Codex SDK</a></p><hr><h2 id="github-action" tabindex="-1">GitHub Action <a class="header-anchor" href="#github-action" aria-label="Permalink to &quot;GitHub Action {#github-action}&quot;">​</a></h2><p><strong>是什么</strong></p><p><code>openai/codex-action@v1</code> 在 GitHub Actions 里安装 CLI 并跑 <code>codex exec</code>。不想自己管 CLI 时用它。</p><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/docs/github-action" target="_blank" rel="noreferrer">GitHub Action</a></p><hr><h2 id="app-server" tabindex="-1">App Server <a class="header-anchor" href="#app-server" aria-label="Permalink to &quot;App Server {#app-server}&quot;">​</a></h2><p><strong>是什么</strong></p><p>给富客户端（含 VS Code 扩展）用的 JSON-RPC 接口，也是 <code>codex --remote</code> 背后的进程。CI 用 SDK 或 <code>codex exec</code>，不要在公网自建监听。</p><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/docs/app-server" target="_blank" rel="noreferrer">App Server</a></p><hr><h2 id="codex-micro" tabindex="-1">Codex Micro <a class="header-anchor" href="#codex-micro" aria-label="Permalink to &quot;Codex Micro {#codex-micro}&quot;">​</a></h2><p><strong>是什么</strong></p><p>限量的 Work Louder 键盘：Agent Key 亮灯，触发桌面 ChatGPT 动作。硬件配件，不是 Codex 入口。</p><p><strong>官方文档</strong>：<a href="https://learn.chatgpt.com/docs/features/codex-micro" target="_blank" rel="noreferrer">Codex Micro</a></p><hr><h2 id="atlas" tabindex="-1">Atlas（已下线） <a class="header-anchor" href="#atlas" aria-label="Permalink to &quot;Atlas（已下线） {#atlas}&quot;">​</a></h2><p><strong>是什么</strong></p><p>曾经的独立 ChatGPT 浏览器。官方已把基于浏览器的代理能力迁进 ChatGPT 和 Codex，并给出停止日 <strong>2026-08-09</strong>。</p><p><strong>不是什么</strong></p><p>不是现行产品，也不是需要单独成页的「桌面 superapp」。现行替代：桌面内置浏览器、Chrome 扩展、Work 的 Cloud Browser。</p><p><strong>官方文档</strong>：<a href="https://help.openai.com/en/articles/20001371-evolving-atlas-into-chatgpt-for-browser-based-agentic-work" target="_blank" rel="noreferrer">Evolving Atlas</a> · <a href="https://openai.com/index/chatgpt-for-your-most-ambitious-work/" target="_blank" rel="noreferrer">2026-07-09 公告</a></p><hr><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./codex-cheatsheet.html">Codex 速查表</a> — 命令、配置、错误速查</li><li><a href="./codex-cookbook.html">Codex Cookbook</a> — 按任务组织的实操配方</li><li><a href="./codex-cli.html">Codex CLI 教程</a> — 从安装到核心功能</li><li><a href="./chatgpt-work.html">ChatGPT Work</a> — 知识工作代理</li><li><a href="./sites.html">Sites</a> — 托管网页和应用</li><li><a href="./codex-cloud.html">Codex Cloud</a> · <a href="./codex-ide.html">IDE</a> · <a href="./codex-remote.html">Remote</a></li><li><a href="./codex-security.html">Security</a> · <a href="./codex-chrome.html">Chrome</a></li><li><a href="./integration.html">项目集成</a> — 把 Codex 接入真实项目</li><li><a href="./">学习地图</a> — 完整学习路径</li></ul>`,287)])])}const b=t(a,[["render",d]]);export{k as __pageData,b as default};
